mapper.select:
SELECT q.id
FROM queue q
INNER JOIN appointment a ON a.id = q.appointment_id
INNER JOIN source s ON s.id = a.source_id
WHERE a.doctor_id = #{doctorId}
  AND s.visit_date = #{visitDate}
  AND s.time_period = #{timePeriod}
  AND q.status = '等待接诊'
ORDER BY q.sort_no ASC, q.sign_time ASC, q.id ASC
FOR UPDATE

mapper.update:
UPDATE queue
SET sort_no = #{sortNo}
WHERE id = #{queueId}
